// [개인화 레이어 입력] 프론트에서 받은 사용자 신호(선택 아티스트, 장바구니)를 정리하고
// 카탈로그 후보별 사용자 관심 점수를 계산한다. (AI 호출 없음)
const body = $json.body || $json;

const artist = String(body.artist || '세븐틴').replace(/\s*\(.*?\)\s*/g, '').trim().slice(0, 30);
const artistId = String(body.artistId || '').slice(0, 30);
// 캐시 만료 기준일 (한국 시간)
const date = new Date(Date.now() + 9 * 3600 * 1000).toISOString().slice(0, 10);

const catalog = (Array.isArray(body.catalog) ? body.catalog : [])
  .filter(g => g && g.id)
  .slice(0, 50)
  .map(g => ({
    id: String(g.id),
    name: String(g.name || ''),
    category: String(g.category || 'ETC').toUpperCase(),
    price: Number(g.price) || 0,
    artist: g.artist ? String(g.artist) : '',
  }));
const cart = (Array.isArray(body.cart) ? body.cart : []).slice(0, 30).map(c => ({
  id: String(c.id || ''),
  title: String(c.title || ''),
  quantity: Number(c.quantity) || 1,
  badges: Array.isArray(c.badges) ? c.badges.map(String) : [],
}));

// 장바구니 문구로 관심 카테고리 추정
const CATEGORY_KEYWORDS = {
  ALBUM: ['ALBUM', '앨범', 'MINI', 'SET', 'VER'],
  CONCERT: ['CONCERT', 'TOUR', '콘서트', '투어', 'LIGHT STICK', '응원봉'],
  COLLECTION: ['PHOTOCARD', '포토카드', 'POB', '특전', 'COLLECTION'],
  MEMBERSHIP: ['MEMBERSHIP', '멤버십', 'FANCLUB', '팬클럽'],
};
const interest = {};
for (const item of cart) {
  const text = `${item.title} ${item.badges.join(' ')}`.toUpperCase();
  let matched = false;
  for (const [cat, words] of Object.entries(CATEGORY_KEYWORDS)) {
    if (words.some(w => text.includes(w))) {
      interest[cat] = (interest[cat] || 0) + item.quantity;
      matched = true;
    }
  }
  if (!matched) interest.ALBUM = (interest.ALBUM || 0) + item.quantity;
}

// 이미 담은 상품과 함께 사기 좋은 카테고리에 보너스
const COMPLEMENT = { ALBUM: ['COLLECTION', 'CONCERT'], CONCERT: ['MEMBERSHIP'], COLLECTION: ['ALBUM'], MEMBERSHIP: ['CONCERT'] };
const cartIds = new Set(cart.map(c => c.id));

const candidates = catalog
  .filter(g => !g.artist || !artistId || g.artist === artistId)
  .map(g => {
    let score = (interest[g.category] || 0) * 2;
    for (const [cat, qty] of Object.entries(interest)) {
      if ((COMPLEMENT[cat] || []).includes(g.category)) score += qty;
    }
    if (cartIds.has(g.id)) score -= 5;
    return { ...g, score };
  })
  .sort((a, b) => b.score - a.score);

const rssUrl = 'https://news.google.com/rss/search?q='
  + encodeURIComponent(`${artist} when:7d`)
  + '&hl=ko&gl=KR&ceid=KR:ko';

return [{ json: { date, artist, artistId, cart, interest, candidates, rssUrl } }];

// 캐시에 저장된 아티스트 뉴스 맥락을 복원한다.
let data = {};
try {
  data = JSON.parse($json.curation_data || '{}');
} catch (e) {
  data = {};
}
return [{ json: { contexts: [], ...data, cached: true } }];

// [맥락 레이어] 아티스트 최신 기사(7일)를 정리하고, 뉴스 맥락 ↔ 굿즈 매핑 프롬프트를 만든다.
// 사용자 정보는 넣지 않는다. (아티스트 단위로 하루 1회 캐시되는 결과이므로)
const ctx = $('Build User Context').first().json;
const xml = typeof $json.data === 'string' ? $json.data : '';

const decode = s => s
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .trim();
const pick = (block, tag) => {
  const m = block.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`));
  return m ? decode(m[1]) : '';
};

const seen = new Set();
let articles = [];
for (const m of xml.matchAll(/<item>([\s\S]*?)<\/item>/g)) {
  const block = m[1];
  const source = pick(block, 'source');
  let title = pick(block, 'title');
  if (source && title.endsWith(` - ${source}`)) title = title.slice(0, -(source.length + 3));
  if (!title || seen.has(title)) continue;
  seen.add(title);
  const date = new Date(pick(block, 'pubDate'));
  articles.push({ title, source, pubDate: isNaN(date) ? '' : date.toISOString().slice(0, 10) });
}
articles = articles.sort((a, b) => b.pubDate.localeCompare(a.pubDate)).slice(0, 10);

const goods = ctx.candidates.map(({ id, name, category, price }) => ({ id, name, category, price }));

const prompt = `너는 K-POP 공식 굿즈 샵의 MD 큐레이터다.
"${ctx.artist}"의 최근 7일 기사 제목에서 팬들이 관심 가질 활동 맥락을 찾고, 각 맥락에 어울리는 공식 굿즈를 1:1로 연결하라.

[최근 기사 제목]
${articles.length ? articles.map((a, i) => `${i + 1}. [${a.pubDate}] ${a.title}`).join('\n') : '(최근 기사 없음)'}

[굿즈 후보]
${JSON.stringify(goods)}

[규칙]
1. 맥락은 최대 4개. 무대/투어, 공항/패션, 음반/포토카드 수집, 멤버십 혜택 같은 서로 다른 팬덤 접점이 되도록 한다.
2. 각 맥락에 굿즈 id 하나를 연결한다. id는 후보 목록의 값만 쓰고 중복하지 않는다.
3. 기사 제목에 없는 일정, 수치, 발언은 지어내지 않는다. 기사가 없으면 일반적인 팬 활동 맥락으로 쓴다.
4. reason은 기사 맥락과 굿즈를 잇는 한두 문장 한국어.
5. 아래 JSON만 출력한다.

{"headline":"섹션 한 줄 요약","contextKeyword":"짧은 키워드","contexts":[{"id":"굿즈 id","category_badge":"짧은 배지","headline":"카드 제목","reason":"추천 이유"}]}`;

return [{ json: { articles, prompt } }];

// Gemini가 만든 뉴스 맥락 매핑을 검증한다. 후보에 없는 id와 중복은 제거.
const ctx = $('Build User Context').first().json;
const validIds = new Set(ctx.candidates.map(g => g.id));
const { articles } = $('Build Context Prompt').first().json;

let parsed = null;
try {
  const parts = ($json.candidates && $json.candidates[0] && $json.candidates[0].content
    && $json.candidates[0].content.parts) || [];
  parsed = JSON.parse(parts.map(p => p.text || '').join('').replace(/```json|```/g, '').trim());
} catch (e) {
  parsed = null;
}

const clip = (v, n) => String(v || '').trim().slice(0, n);
const used = new Set();
const contexts = [];
for (const c of (parsed && Array.isArray(parsed.contexts) ? parsed.contexts : [])) {
  const id = c && String(c.id);
  if (!validIds.has(id) || used.has(id)) continue;
  used.add(id);
  contexts.push({
    id,
    category_badge: clip(c.category_badge, 30),
    headline: clip(c.headline, 80),
    reason: clip(c.reason, 200),
  });
  if (contexts.length === 4) break;
}

return [{
  json: {
    headline: contexts.length ? clip(parsed.headline, 80) : '',
    contextKeyword: contexts.length ? clip(parsed.contextKeyword, 30) : '',
    contexts,
    articleCount: articles.length,
    cached: false,
  },
}];

// [개인화 레이어] 아티스트 뉴스 맥락(캐시/신규)에 사용자 관심 점수를 더해 재정렬한다.
// 요청마다 실행되지만 AI 호출이 없어 수 ms 안에 끝난다.
const user = $('Build User Context').first().json;
const scoreOf = new Map(user.candidates.map(g => [g.id, g]));
const cartIds = new Set(user.cart.map(c => c.id));
const contexts = (Array.isArray($json.contexts) ? $json.contexts : []).filter(c => scoreOf.has(c.id));

// 장바구니에서 해당 카테고리와 관련된 대표 상품명
const cartHint = user.cart.length ? user.cart[0].title : '';

// 맥락 순위 점수(앞쪽일수록 높음) + 사용자 관심 점수
const ranked = contexts
  .filter(c => !cartIds.has(c.id))
  .map((c, i) => ({ ...c, total: (contexts.length - i) + scoreOf.get(c.id).score * 2 }))
  .sort((a, b) => b.total - a.total);

const picks = ranked.slice(0, 4).map(c => {
  const g = scoreOf.get(c.id);
  const personal = g.score > 0 && cartHint
    ? ` 장바구니의 '${cartHint}'와(과) 함께 보기 좋아요.`
    : '';
  return {
    id: c.id,
    headline: c.headline || g.name,
    category_badge: g.score > 0 ? `${c.category_badge || g.category} · 맞춤` : (c.category_badge || g.category),
    reason: `${c.reason}${personal}`.trim(),
  };
});

// 맥락이 부족하면 사용자 관심 점수 순으로 채움
const used = new Set(picks.map(p => p.id));
for (const g of user.candidates) {
  if (picks.length >= 2) break;
  if (used.has(g.id) || cartIds.has(g.id)) continue;
  used.add(g.id);
  picks.push({
    id: g.id,
    headline: `${user.artist} 팬을 위한 ${g.category} 추천`,
    category_badge: g.score > 0 ? '관심사 기반' : 'MD PICK',
    reason: g.score > 0
      ? `장바구니에 담은 상품과 함께 보기 좋은 ${g.category} 아이템입니다.`
      : `${user.artist} 팬들이 많이 찾는 공식 굿즈입니다.`,
  });
}

return [{
  json: {
    headline: $json.headline || `${user.artist} 맞춤 큐레이션`,
    contextKeyword: $json.contextKeyword || 'AI REALTIME',
    source: contexts.length ? 'n8n Gemini 분석' : 'n8n 규칙 기반 추천',
    cached: Boolean($json.cached),
    signals: { artist: user.artist, cartCount: user.cart.length, interest: user.interest },
    recommendedGoods: picks,
  },
}];

// AI 맥락 매핑이 성공한 경우만 아티스트별 하루 캐시에 적재한다.
if (!Array.isArray($json.contexts) || $json.contexts.length === 0) return [];

const ctx = $('Build User Context').first().json;
const { cached, ...data } = $json;
return [{
  json: {
    date: ctx.date,
    artist: ctx.artist,
    curation_data: JSON.stringify(data),
  },
}];
